conversion:
// js
const terms = ctx.subject.employment.terms;
const rate = get(terms, 'rate', {});
const monthly =
	get(rate, 'unit', 'MONTHLY') === 'MONTHLY'
		? Number(get(rate, 'amount', 0))
		: Number(get(ctx, 'base_pay', 0));
const hourly = (monthly * ctx.lookup.months_per_year) / (ctx.lookup.weeks_per_year * ctx.lookup.full_time_weekly_hours);
const category = get(terms, 'statutory_work_category', 'NON_MANUAL');
const capped =
	category === 'NON_MANUAL' && monthly > ctx.lookup.non_workman_monthly_ceiling
		? Math.min(hourly, ctx.lookup.non_workman_hourly_cap)
		: hourly;
return Number(ctx.entry.quantity) * capped * ctx.lookup.multiplier;

